# Mother Soil Equipments - safe language + Google Sheets patch
$ErrorActionPreference = "Stop"

$ProjectPath = "C:\Users\Admin\projects\mse\mother-soil-equipments"
if (-not (Test-Path $ProjectPath)) {
    Write-Host "Project folder not found: $ProjectPath" -ForegroundColor Red
    exit 1
}

Set-Location $ProjectPath

$encoded = @"

"@

$temp = Join-Path $env:TEMP "mse-language-sheets-patch.js"
[System.IO.File]::WriteAllBytes(
    $temp,
    [Convert]::FromBase64String($encoded)
)

Write-Host ""
Write-Host "Running safe patcher..." -ForegroundColor Cyan
Write-Host ""

node $temp

$exitCode = $LASTEXITCODE
Remove-Item $temp -Force -ErrorAction SilentlyContinue

if ($exitCode -ne 0) {
    Write-Host ""
    Write-Host "PATCH FAILED. Your backup remains untouched." -ForegroundColor Red
    exit $exitCode
}

Write-Host ""
Write-Host "Done." -ForegroundColor Green
Write-Host ""
Write-Host "Now run:"
Write-Host "  npm run build"
Write-Host ""
